    "content": "// Sample data for components:charts/metric-switcher: 180 days of storefront metrics (Jan 2 to\n// Jun 30, 2026), one value per day. Each range compares its last N days with the N days before.\n\nexport type Metric = {\n    key: string;\n    label: string;\n    /** 'sum' (totals: orders, revenue) or 'avg' (levels: users, latency) for the tile value. */\n    agg: 'sum' | 'avg';\n    format: 'count' | 'money' | 'ms';\n    lowerIsBetter?: boolean;\n    caption: string;\n    light: string;\n    dark: string;\n};\n\nexport type Annotation =\n    | { type: 'line'; date: string; label: string }\n    | { type: 'band'; from: string; to: string; label: string };\n\nexport type MetricRange = { key: string; label: string; days: number; tickEvery: number };\n\nexport const METRICS: Metric[] = [\n    {\n        key: 'orders',\n        label: 'Orders',\n        agg: 'sum',\n        format: 'count',\n        caption: 'Orders per day',\n        light: 'teal-500',\n        dark: 'teal-500',\n    },\n    {\n        key: 'revenue',\n        label: 'Revenue',\n        agg: 'sum',\n        format: 'money',\n        caption: 'Revenue per day',\n        light: 'amber-500',\n        dark: 'amber-500',\n    },\n    {\n        key: 'users',\n        label: 'Active Users',\n        agg: 'avg',\n        format: 'count',\n        caption: 'Active Users per day',\n        light: 'sky-500',\n        dark: 'sky-500',\n    },\n    {\n        key: 'latency',\n        label: 'p95 Latency',\n        agg: 'avg',\n        format: 'ms',\n        lowerIsBetter: true,\n        caption: 'p95 Latency per day, in ms',\n        light: 'violet-500',\n        dark: 'violet-500',\n    },\n];\n\nexport const RANGES: MetricRange[] = [\n    { key: '7D', label: '7D', days: 7, tickEvery: 1 },\n    { key: '30D', label: '30D', days: 30, tickEvery: 7 },\n    { key: '90D', label: '90D', days: 90, tickEvery: 14 },\n];\n\nexport const ANNOTATIONS: Annotation[] = [\n    { type: 'line', date: '2026-06-04', label: 'v4.2 Release' },\n    { type: 'band', from: '2026-06-12', to: '2026-06-14', label: 'Summer Sale' },\n];\n\nexport const START_DATE = '2026-01-02';\n\nexport const SERIES: Record<string, number[]> = {\n    orders: [\n        94, 82, 75, 90, 91, 98, 100, 101, 81, 76, 86, 98, 97, 97, 108, 81, 77, 91, 105, 100, 106, 110, 79, 80, 102, 96,\n        103, 98, 113, 82, 79, 99, 100, 100, 106, 103, 89, 87, 96, 100, 107, 112, 113, 84, 83, 106, 109, 99, 107, 120,\n        96, 85, 101, 108, 101, 117, 111, 90, 88, 107, 110, 106, 119, 124, 89, 90, 101, 119, 111, 113, 120, 95, 89, 101,\n        117, 110, 112, 126, 104, 88, 104, 116, 113, 121, 127, 101, 94, 107, 117, 118, 115, 121, 107, 96, 117, 125, 116,\n        128, 126, 99, 97, 109, 119, 127, 119, 136, 106, 101, 111, 126, 130, 127, 132, 107, 100, 128, 132, 116, 133, 140,\n        104, 95, 130, 128, 130, 132, 140, 110, 99, 118, 121, 126, 139, 135, 107, 96, 117, 131, 130, 131, 136, 105, 99,\n        135, 124, 126, 136, 141, 111, 100, 127, 142, 133, 132, 136, 123, 105, 125, 137, 127, 140, 221, 172, 176, 127,\n        139, 145, 150, 139, 126, 114, 128, 134, 126, 138, 129, 116, 109, 122, 130,\n    ],\n    revenue: [\n        3914, 3436, 3253, 3893, 4215, 4344, 4451, 4497, 3612, 3389, 3755, 4546, 4452, 4157, 4928, 3665, 3598, 4027,\n        4896, 4454, 4736, 4903, 3367, 3405, 4511, 4472, 4645, 4214, 5086, 3785, 3351, 4506, 4258, 4439, 4602, 4750,\n        4104, 4053, 4308, 4477, 4789, 5011, 4878, 3797, 3749, 5034, 4794, 4722, 4932, 5596, 4423, 3817, 4556, 4711,\n        4535, 5415, 5282, 4165, 3886, 5099, 5242, 5046, 5434, 5538, 4210, 4206, 4637, 5326, 5217, 5354, 5583, 4449,\n        4226, 4857, 5274, 5303, 5258, 5615, 4852, 4232, 4675, 5580, 5052, 5319, 6189, 4834, 4365, 5051, 5709, 5381,\n        5503, 5800, 4790, 4549, 5421, 5908, 5138, 5955, 6162, 4849, 4308, 5009, 5488, 6200, 5878, 6665, 5007, 4971,\n        5128, 6174, 5819, 5834, 6442, 4962, 4629, 5996, 6001, 5239, 6196, 6830, 5008, 4515, 6335, 5961, 6219, 6334,\n        6707, 5162, 4524, 5512, 5702, 5727, 6341, 6287, 5203, 4428, 5599, 6181, 6015, 6461, 6372, 5066, 4725, 6168,\n        6059, 6092, 6360, 6926, 5492, 4651, 4918, 5555, 4980, 5018, 5402, 4968, 4030, 4920, 5404, 4948, 5550, 8929,\n        6577, 6684, 4885, 5618, 5603, 5806, 5232, 5016, 4292, 5198, 6724, 6096, 6793, 6522, 5575, 5379, 6025, 6157,\n    ],\n    users: [\n        1638, 1504, 1453, 1652, 1653, 1683, 1684, 1650, 1577, 1454, 1610, 1696, 1680, 1648, 1672, 1534, 1525, 1656,\n        1656, 1638, 1676, 1769, 1626, 1519, 1653, 1677, 1782, 1697, 1822, 1607, 1606, 1761, 1755, 1709, 1765, 1838,\n        1697, 1564, 1770, 1766, 1764, 1829, 1789, 1622, 1600, 1766, 1787, 1792, 1824, 1888, 1678, 1658, 1818, 1853,\n        1884, 1894, 1851, 1742, 1686, 1898, 1852, 1808, 1948, 1994, 1798, 1744, 1841, 1945, 1931, 1967, 1898, 1758,\n        1737, 1933, 1985, 1911, 1959, 2033, 1795, 1759, 1855, 1951, 1989, 1998, 1996, 1847, 1840, 1945, 1980, 1922,\n        2069, 2038, 1874, 1842, 1913, 2075, 2081, 2057, 2025, 1888, 1779, 1980, 1996, 2098, 2047, 2149, 1914, 1875,\n        2011, 2037, 2065, 2063, 2204, 1877, 1895, 2059, 2130, 2041, 2143, 2150, 1947, 1936, 2117, 2061, 2187, 2192,\n        2218, 2024, 1980, 2158, 2164, 2195, 2200, 2224, 1965, 1882, 2095, 2091, 2111, 2148, 2147, 1931, 1818, 2011,\n        2059, 2018, 2073, 2084, 1877, 1821, 1992, 1984, 1905, 1882, 1950, 1802, 1697, 1886, 1919, 1853, 1860, 2227,\n        2031, 1991, 1847, 1818, 1766, 1817, 1781, 1605, 1621, 1719, 1717, 1693, 1769, 1730, 1553, 1555, 1587, 1626,\n    ],\n    latency: [\n        153, 158, 153, 150, 151, 154, 167, 158, 144, 153, 161, 164, 162, 151, 158, 151, 150, 160, 157, 168, 166, 160,\n        163, 154, 166, 160, 170, 160, 163, 157, 151, 160, 171, 153, 169, 165, 161, 153, 164, 158, 169, 163, 165, 154,\n        152, 171, 167, 168, 160, 160, 152, 163, 157, 162, 161, 167, 157, 163, 166, 174, 165, 173, 158, 168, 167, 161,\n        163, 174, 162, 174, 170, 155, 163, 172, 172, 163, 163, 163, 163, 157, 175, 160, 164, 169, 163, 169, 170, 166,\n        175, 168, 177, 170, 162, 157, 165, 163, 175, 171, 164, 167, 171, 174, 165, 176, 178, 167, 159, 167, 173, 176,\n        180, 181, 178, 165, 175, 167, 172, 175, 171, 168, 166, 176, 182, 176, 168, 169, 172, 161, 166, 182, 168, 178,\n        170, 178, 171, 177, 180, 181, 175, 180, 177, 169, 163, 175, 176, 177, 184, 182, 170, 168, 180, 186, 175, 157,\n        152, 147, 147, 148, 148, 153, 162, 164, 156, 168, 161, 162, 159, 150, 161, 145, 152, 164, 161, 151, 166, 164,\n        160, 167, 167, 161,\n    ],\n};\n"
