    "content": "// Sample data for components:charts/revenue-trend: 90 days of revenue (Jul 19 to Oct 16, 2026; the last\n// day is in progress) and 12 months (Nov 2025 to Oct 2026, the last month in progress).\n\n/** [ISO date, subscriptions, one-time, orders, net 90 days earlier, net on the same weekday last year]. */\nexport type DailyRow = [string, number, number, number, number, number];\n\n/** [YYYY-MM, subscriptions, one-time, orders, net in the same month last year]. */\nexport type MonthRow = [string, number, number, number, number];\n\nexport type RevenueRange = {\n    key: string;\n    label: string;\n    /** Days of DAILY to show; omit for the monthly range. */\n    days?: number;\n    phrase: string;\n    /** Label every n-th point counting back from the last. */\n    tickEvery: number;\n    /** Tile deltas (%) for subscriptions, one-time and orders vs each comparison. */\n    deltas: Record<string, [number, number, number]>;\n};\n\nexport const RANGES: RevenueRange[] = [\n    {\n        key: '7D',\n        label: '7D',\n        days: 7,\n        phrase: 'last 7 days',\n        tickEvery: 1,\n        deltas: { previous: [0.6, -2.5, 0.3], lastYear: [30.4, 3.2, 23.8] },\n    },\n    {\n        key: '30D',\n        label: '30D',\n        days: 30,\n        phrase: 'last 30 days',\n        tickEvery: 7,\n        deltas: { previous: [2.6, 16.7, 5.1], lastYear: [29.2, 22.7, 28.0] },\n    },\n    {\n        key: '90D',\n        label: '90D',\n        days: 90,\n        phrase: 'last 90 days',\n        tickEvery: 21,\n        deltas: { previous: [6.5, 5.2, 6.6], lastYear: [28.8, 15.7, 26.5] },\n    },\n    {\n        key: '12M',\n        label: '12M',\n        phrase: 'last 12 months',\n        tickEvery: 2,\n        deltas: { previous: [29.1, 14.8, 26.4] },\n    },\n];\n\n/** How much of today has been counted (14:20 UTC). */\nexport const TODAY_FRACTION = 860 / 1440;\nexport const TODAY_LABEL = '14:20 UTC';\n\nexport const DAILY: DailyRow[] = [\n    ['2026-07-19', 11846, 1931, 44, 16497, 10679],\n    ['2026-07-20', 11903, 5254, 49, 18519, 13864],\n    ['2026-07-21', 11908, 5554, 49, 17055, 14955],\n    ['2026-07-22', 12208, 5861, 52, 17954, 13831],\n    ['2026-07-23', 12059, 5412, 50, 15658, 13356],\n    ['2026-07-24', 12172, 4779, 51, 13948, 13232],\n    ['2026-07-25', 11700, 2159, 44, 13449, 10977],\n    ['2026-07-26', 12231, 1635, 45, 16420, 10895],\n    ['2026-07-27', 11865, 5626, 49, 17237, 13873],\n    ['2026-07-28', 11814, 5940, 51, 16524, 13686],\n    ['2026-07-29', 12363, 5536, 51, 17578, 14986],\n    ['2026-07-30', 12356, 4933, 50, 25532, 13976],\n    ['2026-07-31', 12132, 4694, 50, 16429, 26400],\n    ['2026-08-01', 21261, 2533, 78, 13757, 13449],\n    ['2026-08-02', 14819, 1637, 54, 16207, 11002],\n    ['2026-08-03', 11915, 5662, 50, 17576, 13777],\n    ['2026-08-04', 12003, 6214, 51, 17751, 13800],\n    ['2026-08-05', 12052, 4879, 50, 17565, 14155],\n    ['2026-08-06', 11943, 4942, 49, 16551, 13510],\n    ['2026-08-07', 12354, 4528, 50, 14011, 13342],\n    ['2026-08-08', 12172, 1977, 45, 13641, 11427],\n    ['2026-08-09', 12345, 2008, 46, 16922, 10901],\n    ['2026-08-10', 12142, 4346, 49, 18047, 14432],\n    ['2026-08-11', 12201, 6077, 52, 16961, 15023],\n    ['2026-08-12', 12493, 4994, 52, 16333, 13800],\n    ['2026-08-13', 11777, 4390, 48, 16147, 13513],\n    ['2026-08-14', 12114, 4080, 49, 14024, 13206],\n    ['2026-08-15', 11954, 1897, 44, 13624, 11537],\n    ['2026-08-16', 12465, 1609, 45, 16381, 11268],\n    ['2026-08-17', 12581, 4896, 52, 16722, 13620],\n    ['2026-08-18', 12082, 5024, 49, 17705, 15095],\n    ['2026-08-19', 12171, 4195, 49, 17083, 13888],\n    ['2026-08-20', 11859, 4664, 49, 16425, 14106],\n    ['2026-08-21', 12493, 5167, 52, 14287, 13747],\n    ['2026-08-22', 12313, 2525, 47, 13911, 11507],\n    ['2026-08-23', 12359, 1852, 46, 17018, 11255],\n    ['2026-08-24', 11923, 4969, 49, 17411, 13614],\n    ['2026-08-25', 12303, 5112, 51, 18353, 14562],\n    ['2026-08-26', 11988, 5534, 50, 17659, 13907],\n    ['2026-08-27', 12371, 5036, 51, 15555, 14847],\n    ['2026-08-28', 12401, 4418, 50, 14188, 12967],\n    ['2026-08-29', 12296, 2415, 46, 13514, 11462],\n    ['2026-08-30', 12158, 1680, 45, 27950, 11480],\n    ['2026-08-31', 11901, 4904, 50, 20217, 22477],\n    ['2026-09-01', 22808, 7798, 91, 17909, 18735],\n    ['2026-09-02', 15413, 7470, 65, 16810, 25066],\n    ['2026-09-03', 12481, 6617, 54, 16463, 15044],\n    ['2026-09-04', 12018, 5644, 50, 13515, 14147],\n    ['2026-09-05', 12396, 3145, 48, 14331, 11779],\n    ['2026-09-06', 12656, 2693, 48, 17816, 11730],\n    ['2026-09-07', 12014, 7411, 54, 17856, 15624],\n    ['2026-09-08', 12117, 5626, 51, 18239, 15444],\n    ['2026-09-09', 12315, 6349, 53, 18305, 15687],\n    ['2026-09-10', 12593, 17476, 73, 15648, 15667],\n    ['2026-09-11', 12293, 6215, 52, 14336, 14588],\n    ['2026-09-12', 12301, 2895, 47, 17399, 11811],\n    ['2026-09-13', 12487, 2439, 47, 17688, 11642],\n    ['2026-09-14', 12392, 6317, 52, 17043, 14392],\n    ['2026-09-15', 12383, 7495, 55, 18591, 16578],\n    ['2026-09-16', 11980, 6786, 53, 16383, 15194],\n    ['2026-09-17', 12696, 6571, 55, 17050, 15896],\n    ['2026-09-18', 12057, 5678, 51, 14597, 14353],\n    ['2026-09-19', 12499, 2788, 48, 13928, 16240],\n    ['2026-09-20', 12573, 2030, 47, 26945, 11506],\n    ['2026-09-21', 12663, 6071, 54, 17168, 14498],\n    ['2026-09-22', 12171, 6866, 53, 16671, 14016],\n    ['2026-09-23', 12424, 5568, 53, 17906, 15924],\n    ['2026-09-24', 12611, 6533, 55, 17676, 15385],\n    ['2026-09-25', 12187, 13133, 64, 14464, 14137],\n    ['2026-09-26', 13023, 2438, 49, 14002, 12367],\n    ['2026-09-27', 12381, 2813, 48, 17607, 11228],\n    ['2026-09-28', 12241, 7010, 54, 19112, 14914],\n    ['2026-09-29', 12600, 7318, 55, 26460, 14715],\n    ['2026-09-30', 12590, 6333, 53, 20563, 24673],\n    ['2026-10-01', 23250, 7106, 92, 16749, 17512],\n    ['2026-10-02', 15635, 6172, 64, 14089, 14852],\n    ['2026-10-03', 12736, 3024, 48, 13931, 12152],\n    ['2026-10-04', 13029, 2249, 48, 16725, 11767],\n    ['2026-10-05', 12719, 7163, 56, 17508, 15599],\n    ['2026-10-06', 12517, 15884, 69, 18737, 16687],\n    ['2026-10-07', 12763, 6487, 54, 24006, 15008],\n    ['2026-10-08', 12405, 6025, 53, 17242, 14774],\n    ['2026-10-09', 12426, 5258, 52, 14362, 14215],\n    ['2026-10-10', 12669, 2663, 48, 13503, 12435],\n    ['2026-10-11', 12536, 2587, 48, 16643, 11810],\n    ['2026-10-12', 12719, 7837, 55, 16453, 26278],\n    ['2026-10-13', 12848, 7392, 56, 17443, 16051],\n    ['2026-10-14', 12825, 8163, 58, 17234, 16247],\n    ['2026-10-15', 13095, 6525, 57, 17217, 14753],\n    ['2026-10-16', 7360, 7699, 38, 8423, 8416],\n];\n\nexport const MONTHLY: MonthRow[] = [\n    ['2025-11', 313300, 144000, 1311, 368200],\n    ['2025-12', 329700, 114000, 1322, 350300],\n    ['2026-01', 337400, 128100, 1376, 385600],\n    ['2026-02', 311400, 134800, 1295, 346100],\n    ['2026-03', 350300, 170400, 1485, 416500],\n    ['2026-04', 347600, 150900, 1444, 410200],\n    ['2026-05', 366800, 140500, 1486, 416700],\n    ['2026-06', 361800, 161900, 1510, 413400],\n    ['2026-07', 381900, 146900, 1552, 420900],\n    ['2026-08', 389200, 124200, 1548, 420600],\n    ['2026-09', 385400, 183500, 1632, 450800],\n    ['2026-10', 211500, 102200, 896, 248900],\n];\n"
