   {
    "path": "data.ts",
    "target": "client",
    "content": "// Sample data for components:charts/sync-run-history: one connection's last 24 hourly buckets (UTC, oldest\n// first, the last one open) and its most recent runs.\n\nexport type RunHour = {\n    hour: number;\n    s?: number;\n    p?: number;\n    f?: number;\n    rows?: number;\n    partialRows?: number;\n    vsYesterday?: number | null;\n    p50?: number;\n    max?: number;\n    open?: boolean;\n    paused?: string;\n    issue?: { code: string; runs: number; message: string };\n};\n\nexport type Run = {\n    id: string;\n    status: 'succeeded' | 'partial' | 'failed' | 'running';\n    trigger: 'Scheduled' | 'Manual';\n    /** Minutes before now. */\n    ago: number;\n    started: string;\n    rows?: number;\n    seconds: number;\n    issue?: { code: string; message: string };\n};\n\nexport const CONNECTION = {\n    name: 'bank-settlement-files',\n    id: 'CON-4821',\n    source: 'Google Drive API v3',\n    env: 'Production',\n    every: 'every 15 min',\n    icon: 'folder-sync',\n    now: '14:20',\n    nextSync: '14:32',\n    freshnessSlo: '30m',\n    p50: 33,\n    priorSuccessRate: 94.5,\n};\n\n// Hourly rows: the observed (100-rounded) values less 13 each, so the 24h total reads 189.1K as in ReUI.\nexport const HOURS: RunHour[] = [\n    {\n        hour: 15,\n        s: 4,\n        p: 0,\n        f: 0,\n        rows: 15087,\n        vsYesterday: null,\n        p50: 54,\n        max: 55,\n    },\n    {\n        hour: 16,\n        s: 4,\n        p: 0,\n        f: 0,\n        rows: 12587,\n        vsYesterday: -5,\n        p50: 45,\n        max: 49,\n    },\n    {\n        hour: 17,\n        s: 4,\n        p: 0,\n        f: 0,\n        rows: 11787,\n        vsYesterday: null,\n        p50: 45,\n        max: 47,\n    },\n    { hour: 18, s: 4, p: 0, f: 0, rows: 9487, vsYesterday: 3, p50: 39, max: 42 },\n    {\n        hour: 19,\n        s: 4,\n        p: 0,\n        f: 0,\n        rows: 7487,\n        vsYesterday: -17,\n        p50: 32,\n        max: 33,\n    },\n    {\n        hour: 20,\n        s: 4,\n        p: 0,\n        f: 0,\n        rows: 7387,\n        vsYesterday: null,\n        p50: 32,\n        max: 35,\n    },\n    {\n        hour: 21,\n        s: 2,\n        p: 0,\n        f: 2,\n        rows: 2987,\n        vsYesterday: -34,\n        p50: 16,\n        max: 27,\n        issue: {\n            code: 'E_SCHEMA_HEADER',\n            runs: 2,\n            message: 'Header row missing in BARC_2100.csv. Recovered at 21:32.',\n        },\n    },\n    { hour: 22, s: 4, p: 0, f: 0, rows: 5087, vsYesterday: -2, p50: 25, max: 26 },\n    { hour: 23, s: 4, p: 0, f: 0, rows: 4587, vsYesterday: -4, p50: 26, max: 26 },\n    { hour: 0, s: 4, p: 0, f: 0, rows: 3987, vsYesterday: 31, p50: 24, max: 26 },\n    { hour: 1, s: 4, p: 0, f: 0, rows: 3887, vsYesterday: 6, p50: 24, max: 25 },\n    {\n        hour: 2,\n        paused: 'Nightly maintenance window, so no scheduled sync started.',\n    },\n    { hour: 3, s: 4, p: 0, f: 0, rows: 3687, vsYesterday: 15, p50: 22, max: 23 },\n    {\n        hour: 4,\n        s: 4,\n        p: 0,\n        f: 0,\n        rows: 3687,\n        vsYesterday: null,\n        p50: 23,\n        max: 24,\n    },\n    { hour: 5, s: 4, p: 0, f: 0, rows: 4987, vsYesterday: -6, p50: 26, max: 28 },\n    { hour: 6, s: 4, p: 0, f: 0, rows: 6387, vsYesterday: -8, p50: 30, max: 32 },\n    { hour: 7, s: 4, p: 0, f: 0, rows: 8187, vsYesterday: -2, p50: 32, max: 36 },\n    {\n        hour: 8,\n        s: 2,\n        p: 2,\n        f: 0,\n        rows: 9187,\n        partialRows: 3300,\n        vsYesterday: 66,\n        p50: 59,\n        max: 77,\n        issue: {\n            code: 'W_RATE_LIMIT',\n            runs: 2,\n            message: 'HTTP 429, 3 files deferred.',\n        },\n    },\n    { hour: 9, s: 4, p: 0, f: 0, rows: 12387, vsYesterday: 9, p50: 46, max: 52 },\n    {\n        hour: 10,\n        s: 4,\n        p: 0,\n        f: 0,\n        rows: 13987,\n        vsYesterday: null,\n        p50: 54,\n        max: 57,\n    },\n    {\n        hour: 11,\n        s: 4,\n        p: 0,\n        f: 0,\n        rows: 11587,\n        vsYesterday: -8,\n        p50: 45,\n        max: 47,\n    },\n    {\n        hour: 12,\n        s: 4,\n        p: 0,\n        f: 0,\n        rows: 11787,\n        vsYesterday: 20,\n        p50: 46,\n        max: 48,\n    },\n    {\n        hour: 13,\n        s: 4,\n        p: 1,\n        f: 1,\n        rows: 12287,\n        partialRows: 1800,\n        vsYesterday: 5,\n        p50: 50,\n        max: 120,\n        issue: {\n            code: 'E_LIST_TIMEOUT',\n            runs: 1,\n            message: 'Folder listing timed out after 120s. Recovered at 13:24.',\n        },\n    },\n    {\n        hour: 14,\n        s: 2,\n        p: 0,\n        f: 0,\n        rows: 6587,\n        vsYesterday: null,\n        open: true,\n        p50: 51,\n        max: 55,\n    },\n];\n\nexport const RUNS: Run[] = [\n    {\n        id: 'RUN-48303',\n        status: 'succeeded',\n        trigger: 'Scheduled',\n        ago: 2,\n        started: '14:17:15',\n        rows: 2886,\n        seconds: 47,\n    },\n    {\n        id: 'RUN-48302',\n        status: 'succeeded',\n        trigger: 'Scheduled',\n        ago: 17,\n        started: '14:02:11',\n        rows: 3745,\n        seconds: 55,\n    },\n    {\n        id: 'RUN-48301',\n        status: 'succeeded',\n        trigger: 'Manual',\n        ago: 24,\n        started: '13:55:40',\n        rows: 1210,\n        seconds: 27,\n    },\n    {\n        id: 'RUN-48300',\n        status: 'partial',\n        trigger: 'Scheduled',\n        ago: 32,\n        started: '13:47:09',\n        rows: 1788,\n        seconds: 76,\n        issue: { code: 'W_RATE_LIMIT', message: 'HTTP 429, 3 files deferred' },\n    },\n    {\n        id: 'RUN-48299',\n        status: 'succeeded',\n        trigger: 'Scheduled',\n        ago: 47,\n        started: '13:32:12',\n        rows: 3309,\n        seconds: 49,\n    },\n    {\n        id: 'RUN-48298',\n        status: 'succeeded',\n        trigger: 'Scheduled',\n        ago: 62,\n        started: '13:17:08',\n        rows: 3012,\n        seconds: 51,\n    },\n    {\n        id: 'RUN-48297',\n        status: 'failed',\n        trigger: 'Scheduled',\n        ago: 64,\n        started: '13:15:02',\n        seconds: 120,\n        issue: {\n            code: 'E_LIST_TIMEOUT',\n            message: 'Folder listing timed out after 120s',\n        },\n    },\n    {\n        id: 'RUN-48278',\n        status: 'partial',\n        trigger: 'Scheduled',\n        ago: 300,\n        started: '09:20:14',\n        rows: 1484,\n        seconds: 70,\n        issue: { code: 'W_RATE_LIMIT', message: 'HTTP 429, 3 files deferred' },\n    },\n    {\n        id: 'RUN-48277',\n        status: 'partial',\n        trigger: 'Scheduled',\n        ago: 360,\n        started: '08:20:06',\n        rows: 1823,\n        seconds: 77,\n        issue: { code: 'W_RATE_LIMIT', message: 'HTTP 429, 3 files deferred' },\n    },\n    {\n        id: 'RUN-48237',\n        status: 'failed',\n        trigger: 'Scheduled',\n        ago: 1020,\n        started: '21:20:03',\n        seconds: 7,\n        issue: {\n            code: 'E_SCHEMA_HEADER',\n            message: 'Header row missing in BARC_2100.csv',\n        },\n    },\n];\n"
   }
